def getn(state, key):
    try:
        return int(float(str(state.get(key, '0')).strip()))
    except ValueError:
        return 0

def setn(state, key, value):
    state[key] = str(int(value))

def gets(state, key):
    return str(state.get(key, '')).strip()

def cap(value):
    return min(value, 9)

def copy_num(state, dst, src):
    setn(state, dst, getn(state, src))

def add_num(state, dst, src, amount, capped):
    result = getn(state, src) + amount
    setn(state, dst, cap(result) if capped else result)

def double_num(state, key, capped):
    result = getn(state, key) * 2
    setn(state, key, cap(result) if capped else result)

def region_log(state, key, region_key, match, if_match, otherwise):
    state[key] = if_match if gets(state, region_key) == match else otherwise

